/* ============ LOGO (SVG recreado) ============
   variant: "brand" (rojo+azul), "white" (todo blanco), "mono" */
function LogoMark({ variant = "brand" }) {
  const icon = variant === "white" ? "#fff" : "#E5342A";
  return (
    <svg className="eca-logo-svg" viewBox="0 0 132 150" width="1em" height="1em" role="img" aria-hidden="true">
      {/* bombita (círculo) */}
      <circle cx="66" cy="60" r="46" fill="none" stroke={icon} strokeWidth="8" />
      {/* rayo */}
      <path d="M74 22 L46 74 L62 74 L55 118 L88 62 L68 62 L79 22 Z" fill={icon} />
      {/* cuello / curva */}
      <path d="M55 108 q -6 8 4 12" fill="none" stroke={icon} strokeWidth="6" strokeLinecap="round" />
      {/* base (3 líneas) */}
      <rect x="34" y="118" width="64" height="8" rx="4" fill={icon} />
      <rect x="40" y="131" width="52" height="8" rx="4" fill={icon} />
      <rect x="46" y="144" width="40" height="6" rx="3" fill={icon} />
    </svg>
  );
}

function Logo({ variant = "brand", size = "md" }) {
  const blue = variant === "white" ? "#fff" : "#2C7FC4";
  const red = variant === "white" ? "#fff" : "#E5342A";
  const img = variant === "white" ? (CONFIG.logoImageWhite || CONFIG.logoImage) : CONFIG.logoImage;
  if (img) {
    return <img src={img} alt={CONFIG.brand} className={`eca-logo-img s-${size}`} />;
  }
  return (
    <span className={`eca-logo s-${size}`} aria-label={CONFIG.brand}>
      <span className="eca-logo-icon" aria-hidden="true"><LogoMark variant={variant} /></span>
      <span className="eca-logo-word">
        <span className="eca-logo-main" style={{ color: blue }}>Electro Cable</span>
        <span className="eca-logo-sub" style={{ color: red }}>alvear</span>
      </span>
    </span>
  );
}

/* Reveal on scroll */
function Reveal({ children, delay = 0, as: Tag = "div", className = "" }) {
  const ref = useRef(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") { setShown(true); return; }
    const io = new IntersectionObserver((es) => es.forEach((e) => e.isIntersecting && setShown(true)), { threshold: 0.12, rootMargin: "0px 0px -40px 0px" });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return <Tag ref={ref} className={`eca-reveal ${shown ? "is-in" : ""} ${className}`} style={{ transitionDelay: `${delay}ms` }}>{children}</Tag>;
}

